import type { CSSProperties, ReactNode } from "react";
import { backgroundStyle } from "./utils/background";

export interface BackgroundOrchestratorProps {
  /** Album-wide default background. */
  global?: string | null;
  /** Page-level override; when present it is painted on top of the global layer. */
  override?: string | null;
  children: ReactNode;
  className?: string;
  style?: CSSProperties;
}

/**
 * Renders composite stacked backdrop layers: the global album background sits
 * underneath, an optional page-level override is composited over it, and a
 * scrim keeps Hebrew text legible against busy photographic layers.
 */
export function BackgroundOrchestrator({
  global,
  override,
  children,
  className,
  style,
}: BackgroundOrchestratorProps) {
  const globalLayer = backgroundStyle(global);
  const overrideLayer = backgroundStyle(override);
  const hasOverride = Object.keys(overrideLayer).length > 0;

  return (
    <div
      className={["ae-bg", className].filter(Boolean).join(" ")}
      style={style}
    >
      <div className="ae-bg__layer" style={globalLayer} aria-hidden="true" />
      {hasOverride ? (
        <div className="ae-bg__layer" style={overrideLayer} aria-hidden="true" />
      ) : null}
      <div className="ae-bg__content">{children}</div>
    </div>
  );
}
